def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    rich_pressure = 0
    desperate_pressure = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if opp.get('budget', 0) >= 500 and bid >= 90:
                    rich_pressure = max(rich_pressure, bid)
                if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                    desperate_pressure = max(desperate_pressure, bid)

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    max_prev = max(prev_bids) if prev_bids else 0.0
    min_prev = min(prev_bids) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency = 3
    elif hp <= 4 or no_water >= 1:
        urgency = 2
    elif hp <= 6:
        urgency = 1

    if supply >= 23:
        base = 16.0
    elif supply >= 20:
        base = 24.0
    elif supply >= 17:
        base = 36.0
    else:
        base = 52.0

    if max_prev > 0:
        if supply >= 22:
            target = min(base, max(14.0, min_prev + 1.0))
        elif supply >= 19:
            target = max(base, max_prev * 0.42)
        elif supply >= 17:
            target = max(base, max_prev * 0.58)
        else:
            target = max(base, max_prev * 0.72)
    else:
        target = base

    if rich_pressure > 0:
        if urgency == 0 and supply >= 19:
            target = min(target, rich_pressure * 0.38)
        elif urgency == 1:
            target = max(target, rich_pressure * 0.52)
        else:
            target = max(target, rich_pressure * 0.7)

    if desperate_pressure > 0 and urgency >= 2:
        target = max(target, desperate_pressure + 2.0)

    if urgency == 1:
        target = max(target, 48.0)
    elif urgency == 2:
        target = max(target, 72.0)
    elif urgency == 3:
        target = max(target, 96.0)

    if day >= 8 and hp >= 7 and no_water == 0:
        target *= 0.9

    reserve = 0.0
    if day <= 3:
        reserve = 120.0
    elif day <= 6:
        reserve = 70.0
    else:
        reserve = 20.0

    cap = budget
    if budget > reserve:
        cap = budget - reserve + DAILY_SALARY * 0.35
    cap = min(cap, budget)

    if urgency == 3:
        cap = budget

    bid = min(target, cap)
    bid = max(0.0, bid)

    if hp <= 1 or no_water >= 2:
        bid = min(budget, max(bid, 120.0))

    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Gather yesterday's bids from alive opponents who have trace
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_prev = max(yesterday_bids)
    else:
        max_prev = 0

    # Decide bid based on HP and opponent pressure
    if hp <= 2:
        # desperate: bid up to 90% of salary or just above max_prev
        target = max(DAILY_SALARY * 0.9, max_prev + 5)
        return min(budget, target)
    else:
        # comfortable: bid moderately, but if opponent pressure is high, respond
        if max_prev >= DAILY_SALARY * 0.7:
            # need to outbid slightly to not always lose
            target = max_prev + 2
        else:
            target = DAILY_SALARY * 0.5
        target = min(target, budget)
        # Ensure at least 1 to avoid 0 bid when supply is low? Not needed but safe
        return max(1, target)
